        private void SetCrudButton(Button b, string text, int x, int tabIdx)
        {
            b.Location = new Point(x, 7); b.Size = new Size(136, 62);
            b.TabIndex = tabIdx; b.Text = text; b.UseVisualStyleBackColor = true;
        }
        private void SetSearchBox(TextBox tb, string name, int tabIdx)
        {
            tb.Location = new Point(6, 21); tb.Name = name; tb.Size = new Size(399, 34); tb.TabIndex = tabIdx;
        }
        private void SetSearchBtn(Button b, string name, int tabIdx)
        {
            b.Location = new Point(413, 7); b.Name = name; b.Size = new Size(174, 62);
            b.TabIndex = tabIdx; b.Text = "Tìm kiếm"; b.UseVisualStyleBackColor = true;
        }
        private void SetDGV(DataGridView dgv, string name, int tabIdx)
        {
            dgv.ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize;
            dgv.Dock = DockStyle.Fill; dgv.Location = new Point(0, 0);
            dgv.Name = name; dgv.RowHeadersWidth = 60; dgv.TabIndex = tabIdx;
        }
        private void SetFieldPanel(Panel p, string name, int fieldIndex)
        {
            p.Location = new Point(6, 6 + fieldIndex * 94);
            p.Name = name; p.Size = new Size(581, 88); p.TabIndex = fieldIndex;
        }
        private void SetLabel(Label l, string name, string text, Panel parent)
        {
            l.AutoSize = true; l.Font = new Font("Arial", 14F, FontStyle.Bold, GraphicsUnit.Point, 0);
            l.Location = new Point(6, 28); l.Name = name; l.TabIndex = 0; l.Text = text;
            parent.Controls.Add(l);
        }
        private void SetTextBox(TextBox tb, string name, int tabIdx, bool readOnly, Panel parent)
        {
            tb.Location = new Point(220, 24); tb.Name = name; tb.Size = new Size(350, 38);
            tb.TabIndex = 1; tb.ReadOnly = readOnly;
            parent.Controls.Add(tb);
        }
        private void SetReceiptLabel(Label l, string name, string text, int y, Panel parent)
        {
            l.AutoSize = true; l.Font = new Font("Arial", 10F, FontStyle.Bold);
            parent.Controls.Add(l);
            l.Location = new Point(8, y + 4); l.Name = name; l.Text = text;
        }
        private void SetReceiptCombo(ComboBox cb, string name, int y, Panel parent)
        {
            cb.FormattingEnabled = true; cb.Location = new Point(220, y);
            parent.Controls.Add(cb);
            cb.Name = name; cb.Size = new Size(360, 33);
        }

